                let L2: Double = JS.max(2.6 * sc, JS.min(14.0 * sc, sp * 0.034))
                ctx.strokeStyle = C2DStyle(vcA(mixc(VC_HOT, VC_CORAL, vcCl(age * 1.5)), 0.95 * (1.0 - age * 0.45) * near))
                ctx.lineWidth = JS.max(1.0, sc * (2.1 - age * 0.9) * ((once ? 1.25 : 1.0)))
